ExtremeValueTheory.tendsto_measureReal_partialMax_le_exp.{u_1} {Ω : Type u_1}
  {mΩ : MeasurableSpace Ω} {P : MeasureTheory.Measure Ω} {X : ℕ → Ω → ℝ}
  [MeasureTheory.IsProbabilityMeasure P] (hs : ProbabilityTheory.IsStationary X P)
  (hX : ∀ (t : ℕ), Measurable (X t)) {u : ℕ → ℝ} (hD : ExtremeValueTheory.ConditionD X P u)
  (hD' : ExtremeValueTheory.ConditionD' X P u) {τ : ℝ}
  (hτ : Filter.Tendsto (fun n => ↑n * P.real {ω | u n < X 0 ω}) Filter.atTop (nhds τ)) :
  Filter.Tendsto (fun n => P.real {ω | ExtremeValueTheory.partialMax X n ω ≤ u n}) Filter.atTop
    (nhds (Real.exp (-τ)))

ExtremeValueTheory.isExtremeValueDistr_pow {H : CumulativeDistributionFunction}
  (hH : H.IsExtremeValueDistr) {θ : ℝ} (hθ0 : 0 < θ) :
  (H.pow hθ0).IsExtremeValueDistr ∧ ∃ A, A • H = H.pow hθ0

ExtremeValueTheory.HasExtremalIndex.unique.{u_1} {Ω : Type u_1} {mΩ : MeasurableSpace Ω}
  {P : MeasureTheory.Measure Ω} {X : ℕ → Ω → ℝ} {θ θ' : ℝ}
