  (hl : ExtremeValueTheory.HasExceedanceLevels X P) : θ = θ'

ExtremeValueTheory.hasExtremalIndex_movingMax.{u_1} {Ω : Type u_1} {mΩ : MeasurableSpace Ω}
  {P : MeasureTheory.Measure Ω} [MeasureTheory.IsProbabilityMeasure P] {Z : ℕ → Ω → ℝ}
  (hZ : ∀ (t : ℕ), Measurable (Z t)) (hind : ProbabilityTheory.iIndepFun Z P)
  (hid : ∀ (t : ℕ), ProbabilityTheory.IdentDistrib (Z t) (Z 0) P P) :
  ExtremeValueTheory.HasExtremalIndex (fun t ω => max (Z t ω) (Z (t + 1) ω)) P (1 / 2)

ExtremeValueTheory.HasSpectralTailProcess.hasTailProcess.{u_1, u_2} {Ω : Type u_1} {Ω' : Type u_2}
  {mΩ : MeasurableSpace Ω} {mΩ' : MeasurableSpace Ω'} {P : MeasureTheory.Measure Ω}
  [MeasureTheory.IsProbabilityMeasure P] {X : ℤ → Ω → ℝ} {α : ℝ} {Q : MeasureTheory.Measure Ω'}
  [MeasureTheory.IsProbabilityMeasure Q] {Θ : ℤ → Ω' → ℝ} (hα : 0 < α)
  (hX : ∀ (t : ℤ), Measurable (X t)) (hΘm : ∀ (t : ℤ), Measurable (Θ t))
  (h : ExtremeValueTheory.HasSpectralTailProcess P X α Q Θ) :
  ExtremeValueTheory.HasTailProcess P X α ((ProbabilityTheory.paretoMeasure 1 α).prod Q) fun t p =>
    p.1 * Θ t p.2

ExtremeValueTheory.HasSpectralTailProcess.lintegral_timeChange.{u_1, u_2} {Ω : Type u_1}
  {Ω' : Type u_2} {mΩ : MeasurableSpace Ω} {mΩ' : MeasurableSpace Ω'} {P : MeasureTheory.Measure Ω}
  [MeasureTheory.IsProbabilityMeasure P] {X : ℤ → Ω → ℝ} {α : ℝ} {Q : MeasureTheory.Measure Ω'}
  [MeasureTheory.IsProbabilityMeasure Q] {Θ : ℤ → Ω' → ℝ} (hα : 0 < α)
  (hX : ∀ (t : ℤ), Measurable (X t)) (hΘm : ∀ (t : ℤ), Measurable (Θ t))
  (hstat : ExtremeValueTheory.HasShiftInvariantWindows P X)
  (h : ExtremeValueTheory.HasSpectralTailProcess P X α Q Θ) (i : ℤ) (S : Finset ℤ)
  {g : (↥S → ℝ) → ENNReal} (hg : Measurable g) :
  ∫⁻ (ω' : Ω'), {ω' | Θ (-i) ω' ≠ 0}.indicator (fun ω' => g fun t => Θ (↑t - i) ω') ω' ∂Q =
    ∫⁻ (ω' : Ω'), (g fun t => Θ (↑t) ω' / |Θ i ω'|) * ENNReal.ofReal (|Θ i ω'| ^ α) ∂Q

ExtremeValueTheory.HasSpectralTailProcess.tendsto_blockRatio.{u_1, u_2} {Ω : Type u_1}
  {Ω' : Type u_2} {mΩ : MeasurableSpace Ω} {mΩ' : MeasurableSpace Ω'} {P : MeasureTheory.Measure Ω}
  [MeasureTheory.IsProbabilityMeasure P] {X : ℤ → Ω → ℝ} {α : ℝ} {Q : MeasureTheory.Measure Ω'}
  [MeasureTheory.IsProbabilityMeasure Q] {Θ : ℤ → Ω' → ℝ} (hα : 0 < α)
  (hX : ∀ (t : ℤ), Measurable (X t)) (hΘm : ∀ (t : ℤ), Measurable (Θ t))
  (hstat : ExtremeValueTheory.HasShiftInvariantWindows P X)
  (h : ExtremeValueTheory.HasSpectralTailProcess P X α Q Θ) {u : ℕ → ℝ}
  (hu : Filter.Tendsto u Filter.atTop Filter.atTop) {r : ℕ → ℕ}
  (hr : Filter.Tendsto r Filter.atTop Filter.atTop)
  (hAC : ExtremeValueTheory.ForwardAntiClusteringAt P X u r) :
  Filter.Tendsto
    (fun n =>
      P.real {ω | ∃ t ∈ Finset.Ico 0 ↑(r n), u n < |X t ω|} / (↑(r n) * P.real {ω | u n < |X 0 ω|}))
    Filter.atTop (nhds (ExtremeValueTheory.candidateExtremalIndex Q Θ α).toReal)

ExtremeValueTheory.HasSpectralTailProcess.hasExtremalIndex_of_isMDependent.{u_1, u_2} {Ω : Type u_1}
  {Ω' : Type u_2} {mΩ : MeasurableSpace Ω} {mΩ' : MeasurableSpace Ω'} {P : MeasureTheory.Measure Ω}
  [MeasureTheory.IsProbabilityMeasure P] {X : ℤ → Ω → ℝ} {α : ℝ} {Q : MeasureTheory.Measure Ω'}
  [MeasureTheory.IsProbabilityMeasure Q] {Θ : ℤ → Ω' → ℝ} (hα : 0 < α)
  (hX : ∀ (t : ℤ), Measurable (X t)) (hΘm : ∀ (t : ℤ), Measurable (Θ t))
  (hstat : ExtremeValueTheory.HasShiftInvariantWindows P X)
  (h : ExtremeValueTheory.HasSpectralTailProcess P X α Q Θ) {m : ℕ}
  (hm : ProbabilityTheory.IsMDependent (fun n => X ↑n) m P) :
  ExtremeValueTheory.HasExtremalIndex (fun k => |X ↑k|) P
    (ExtremeValueTheory.candidateExtremalIndex Q Θ α).toReal

ExtremeValueTheory.RandomIteration.tendstoLawCond_tailChain_iid.{u_1, u_2} {F : Type u_1}
  [MeasurableSpace F] {f : ℝ → F → ℝ} {a b : F → ℝ} {Ω : Type u_2} {mΩ : MeasurableSpace Ω}
  {P : MeasureTheory.Measure Ω} [MeasureTheory.IsProbabilityMeasure P] {X₀ : Ω → ℝ} {V : ℕ → Ω → F}
  (hf : Measurable (Function.uncurry f)) (ha : Measurable a) (hb : Measurable b) {K : Set ℝ}
  (hKm : MeasurableSet K) (hK : ∀ x ∈ K, ∀ (v : F), f x v ∈ K)
  (hfab : ∀ x ∈ K, ∀ (v : F), |f x v - a v * x| ≤ b v) (hX₀ : Measurable X₀)
  (hX₀K : ∀ᵐ (ω : Ω) ∂P, X₀ ω ∈ K) (hV : ∀ (n : ℕ), Measurable (V n))
  (hind : ProbabilityTheory.IndepFun X₀ (fun ω n => V n ω) P)
  (hiid : ProbabilityTheory.iIndepFun V P) {ν : MeasureTheory.Measure F}
  (hlaw : ∀ (n : ℕ), MeasureTheory.Measure.map (V n) P = ν) {S : ℝ → Set ℝ}
  (hS : ∀ (x : ℝ), MeasurableSet (S x)) {μ₀ : MeasureTheory.Measure ℝ}
  [MeasureTheory.IsProbabilityMeasure μ₀]
  (hX0 :
    ExtremeValueTheory.TendstoLawCond P (fun x => X₀ ⁻¹' S x) (fun x ω => X₀ ω / x) Filter.atTop μ₀)
  (k : ℕ) :
  ExtremeValueTheory.TendstoLawCond P (fun x => X₀ ⁻¹' S x)
    (fun x ω t => ExtremeValueTheory.RandomIteration.chain f X₀ V (↑t) ω / x) Filter.atTop
    (MeasureTheory.Measure.map (fun p t => ExtremeValueTheory.RandomIteration.tailWalk a p.1 p.2 ↑t)
      (μ₀.prod (MeasureTheory.Measure.infinitePi fun x => ν)))
